/* Research snapshot; the raw worksheet rows are intentionally preserved separately. */
(()=>{'use strict';const names=[['Áttekintés',0],['Ebédmenü',2],['Étlapok és árak',7],['Versenytársak',4],['Kiszállítás',3],['Marketingbenchmark',5],['Kutatási háttér',6]];let data={},snapshot={},active=0,query='';const root=document.getElementById('intel-app'),old=document.getElementById('app'),nav=document.getElementById('intel-nav');const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=n=>Number.isFinite(+n)&&n!==''&&n!=null?new Intl.NumberFormat('hu-HU').format(Math.round(+n))+' Ft':'Nem igazolt';const source='https://docs.google.com/spreadsheets/d/1eigqlKCEuAGTrBA-96k44CB51-EedJh_FJafi2lb_ww/edit';const link=u=>/^https?:\/\//i.test(u||'')?`<a class="tablelink" target="_blank" rel="noopener" href="${esc(u)}">Forrás ↗</a>`:'—';const rows=n=>(data[n]||[]).slice(1).filter(r=>r.some(x=>x!==null&&x!==''));const title=(tag,h,d)=>`<div class="eyebrow">${tag}</div><h1>${h}</h1><p class="section-intro">${d}</p>`;const note=t=>`<div class="warning">${t}</div>`;const table=(headers,rs)=>`<div class="scroll"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rs.map(r=>`<tr>${r.map(c=>`<td>${c??'—'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;const raw=(n,max=1000)=>{let d=data[n]||[];return `<details><summary>${esc(n)} · eredeti adatsorok (${Math.max(0,d.length-1)})</summary>${table((d[0]||[]).map(x=>x||'—'),d.slice(1,max+1).map(r=>r.map(v=>/^https?:\/\//.test(String(v||''))?link(v):esc(v??'—'))))}</details>`};function overview(){let places=rows('Éttermek').filter(r=>r[0]&&r[1]),dishes=rows('Dashboard adatfolyam').filter(r=>r[0]&&r[5]), channel=rows('Csatornaárak').filter(r=>r[0]);let decisions=[['Kétfogásos ebéd ára','Időben eltérő ajánlatok, néhány végárral','Receptúra és önköltség','Séffel két árszcenáriót számolni','Magas'],['Új étlap és irány','Régi Elefánt- és versenytársi étlapok','Új receptek, kereslet, kapacitás','Fogásokat és pozicionálást egyeztetni','Magas'],['Kiszállítási árak','Párosított csatornaárak, korlátozott minta','Valós jutalék, csomagolás, nettó költség','Fedezetet és csúcsidőt modellezni','Magas'],['Nyitási kommunikáció','Profil- és versenytársmegfigyelések','Dátum, végleges kínálat és felelősök','Felületek és kreatívgyártás ütemezése','Magas']];return note('<b>Fejlesztés alatt álló munkaváltozat.</b> Egyes részletes összehasonlítások, szűrők és az automatikus szinkronizálás még készülnek.')+title('01 / DÖNTÉSI ÁTTEKINTÉS','A következő jó döntés.','A kutatás az újranyitás előkészítését segíti. Az árak különböző dátumokból származó megfigyelések, nem mai árajánlatok.')+`<div class="grid2"><div class="panel"><div class="number">${places.length}</div>éttermi listán szereplő sor · az Elefánttal és jelöltekkel</div><div class="panel"><div class="number">${dishes.length}</div>ármegfigyelés a dashboard adatfolyamában</div><div class="panel"><div class="number">${channel.length}</div>csatornaár-pár · különböző bizonyossággal</div><div class="panel"><div class="number">${Object.keys(data).length}</div>forrásmunkalap a mentett pillanatképben</div></div>`+note('A helylisták átfednek; a szám nem az összes működő versenytárs száma. Az étlapok közt átfedés lehet. A régi Elefánt-étlap történeti referencia.')+`<h2>Mit tudunk, és mire elég?</h2><div class="grid2"><div class="panel"><h3>Az ár nem feltétlenül a végösszeg</h3><p>Az Oliva 2026. október 26–30-i kétfogásos menüje 4400 Ft volt; a rögzített 15% szervizdíjjal 5060 Ft. <b>Döntés:</b> a csomag és a tényleges fizetendő is számít. Bizonyosság: az adott időszakra.</p>${link('https://www.oliva.hu/hu/heti-menu')}</div><div class="panel"><h3>Az összevetett adagok nem mindig azonosak</h3><p>A csatornaár-párok tartalmazzák a párosítás minőségét és a méretkorlátokat. <b>Döntés:</b> az árfelárat ne tekintsük automatikusan azonos adagok piacának. Bizonyosság: páronként eltérő.</p><a href="#" data-go="3">Párok megtekintése →</a></div><div class="panel"><h3>A történeti Elefánt-étlap külön szerepel</h3><p>A november 9-én rögzített árak a régi kínálatot mutatják. <b>Döntés:</b> jó kiinduló viszonyítás, de nem az új étlap. Bizonyosság: történeti.</p>${link('https://www.elefantetterem.hu/hu/etlap')}</div><div class="panel"><h3>Az értékelés és a minta eltérő dolog</h3><p>A táblában platformonként külön értékelések és összefoglalók vannak, köztük történeti aggregátorértékek. <b>Döntés:</b> friss ellenőrzés és szolgáltatási prioritások szükségesek. Bizonyosság: forrástól függ.</p><a href="#" data-go="4">Reputáció →</a></div></div><h2>Döntési tábla</h2>${table(['Döntés','Rendelkezésre áll','Hiányzik','Következő lépés','Prioritás'],decisions.map(x=>x.map(esc)))}<p class="muted">Állapot: egyeztetendő. Ezek munkajavaslatok, nem jóváhagyott döntések.</p>`}
function menu(){let a=rows('Étlap 2026-11-09').filter(r=>r[0]&&r[2]),q=query.toLowerCase(),f=a.filter(r=>r.join(' ').toLowerCase().includes(q));return title('02 / ÉTLAP ÉS ÁRAK','Fogások, kontextussal.','A 2026. november 9-i étlapfelvétel önálló minta. A régebbi részletes adatbázissal nem adjuk össze, mert ugyanazok a fogások mindkettőben előfordulhatnak.')+`<div class="form"><label>Keresés étteremre, fogásra, alapanyagra vagy kategóriára<input id="intel-query" value="${esc(query)}" placeholder="pl. kacsa, leves, Chill"></label><button class="small-btn" id="clear-query">Szűrő törlése</button></div><p>${f.length} találat · kiírt ár, nem feltétlenül szervizdíjas végár</p>`+table(['Étterem','Kategória','Fogás','Kiírt ár','Szervizdíj','Ellenőrzés','Korlát','Forrás'],f.map(r=>[esc(r[0]),esc(r[1]),esc(r[2]),fmt(r[3]),esc(r[4]||'Nem igazolt'),esc(r[6]||'—'),esc(r[8]||'—'),link(r[5])]))+`<h2>Meglévő éttermi és fogásböngésző</h2><p>Az eredeti böngésző a felső, sötét menüsor <b>Ételek</b> és <b>Éttermek</b> pontja alatt továbbra is használható.</p><h2>Kutatói bontás</h2>${raw('Árösszehasonlítás 2026-11-09')}${raw('Étlap tételek')}`}
function lunch(){let a=rows('Napi menü árak').filter(r=>r[0]),pay=window.lunchPay||false;let sorted=[...a].sort((x,y)=>{let v=pay?10:7;return (Number(x[v])||1e12)-(Number(y[v])||1e12)});return title('03 / EBÉDMENÜ','A kiírt ár csak a kezdet.','Időszakhoz kötött ajánlatok: fogásszám, csatorna és járulékos díjak szerint vizsgálandók.')+`<div class="form"><label>Ár nézete<select id="lunch-view"><option value="listed" ${!pay?'selected':''}>Kiírt ár</option><option value="pay" ${pay?'selected':''}>Forrásban rögzített szervizdíjas ár</option></select></label></div>`+note('Az ismeretlen végárat nem tekintjük nullának. A dobozdíj külön látható; a rögzített szervizdíjas összeg nem feltétlenül tartalmaz csomagolást vagy minden egyéb díjat. A külön árazott leves és főétel nem automatikusan menücsomag.')+table(['Hely','Fogás','Csatorna','Ár','Dobozdíj','Időszak','Ellenőrzés','Megjegyzés','Forrás'],sorted.map(r=>[esc(r[2]),esc(r[5]||'—'),esc(r[6]||'—'),fmt(r[pay?10:7]),fmt(r[11]),`${esc(r[13]||'?')} – ${esc(r[14]||'?')}`,esc(r[15]||'—'),esc(r[19]||'—'),link(r[16])]))+`<h2>Ebédár-szcenárió</h2><div class="panel"><div class="form"><label>Tervezett kiírt ár (Ft)<input id="lprice" type="number" min="0" value="3500"></label><label>Változó ételköltség (%)<input id="lcost" type="number" min="0" max="100" value="35"></label></div><p id="lresult"></p><p class="muted">Példaértékek, nem Elefánt-adatok. Az egyszerű különbözet nem profit; további költségeket és adókat nem tartalmaz.</p></div>${raw('Menüminták')}`}
function delivery(){let a=rows('Csatornaárak').filter(r=>r[0]);return title('04 / CSATORNÁK','Helyben vagy kiszállítva?','A párosítások megfigyelések. Az ismeretlen vagy eltérő adag miatt a felár nem minden esetben tekinthető teljesen összehasonlíthatónak.')+table(['Hely','Fogás','Referenciacsatorna','Referencia','Wolt','Eltérés','Eltérés %','Egyezés / adag','Forrás'],a.map(r=>[esc(r[1]),esc(r[2]),esc(r[3]),fmt(r[4]),fmt(r[5]),(typeof r[4]==='number'&&Number.isFinite(r[4])&&r[4]>0&&typeof r[5]==='number'&&Number.isFinite(r[5])&&r[5]>0)?fmt(r[5]-r[4]):'Nem igazolt',(typeof r[4]==='number'&&Number.isFinite(r[4])&&r[4]>0&&typeof r[5]==='number'&&Number.isFinite(r[5])&&r[5]>0)?((r[5]-r[4])/r[4]*100).toFixed(1)+'%':'Nem igazolt',esc([r[10],r[8],r[9],r[27]].filter(Boolean).join(' · ')),link(r[25])+' '+link(r[26])]))+`<h2>Fedezeti kalkulátor</h2><div class="panel"><p>A megadott egységes adózási alapon számolt szemléltető modell. Nem nettó profit; a fix költségeket nem tartalmazza.</p><div class="form">${[['base','Helyszíni ár (Ft)',5000],['food','Ételköltség (%)',35],['comm','Platformjutalék (%)',25],['pack','Csomagolás (Ft)',300],['service','Helyszíni változó költség (Ft)',150],['markup','Kiszállítási árfelár (%)',20]].map(x=>`<label>${x[1]}<input type="number" min="0" id="${x[0]}" value="${x[2]}"></label>`).join('')}</div><div id="marginout"></div><details><summary>Feltételezések és képletek</summary><p>A példában az ételköltség a helyszíni ár százaléka, és mindkét csatornán azonos összeg. A jutalék a kiszállítási eladási árra vonatkozik. Minden bemenetet azonos, pl. áfa nélküli alapon kell megadni; nincs automatikus áfa- vagy jutalékáfa-kezelés. A valós adózás, költségek és jutalékos szerződés külön ellenőrzendő.</p></details></div><h2>Konyhai kapacitás · forgatókönyv</h2><div class="panel"><div class="form">${[['orders','Rendelés / óra',40],['capacity','Kapacitás / óra',50],['prep','Átlagos előkészítés (perc)',20],['share','Kiszállítás aránya (%)',30],['peak','Csúcsidős kereslet / óra',60],['displace','Kiszoruló helyszíni rendelés / óra',4]].map(x=>`<label>${x[1]}<input type="number" min="0" id="${x[0]}" value="${x[2]}"></label>`).join('')}</div><div id="capacityout"></div><p class="muted">A példaszámok nem mért működési adatok; a fedezeti számítás a megadott rendelések teljesítését feltételezi, és túlkapacitás esetén sem korlátozza automatikusan azokat. Az előkészítési idő tájékoztató adat: a megadott kapacitással nem számoljuk újra, mert nem ismerjük a párhuzamos munkaállomásokat.</p></div><h2>Csatornák és nyitvatartás</h2>${raw('Delivery and hours')}`}
function competition(){return window.competitorView(data)+raw('Distance')+raw('Ratings 2026-11-09')+raw('Review themes')+raw('Éttermek')}
let postFilter='';function marketing(){let social=rows('Social and ads'),live=data['Social live read 2026-11-09']||[],groups=['Elefánt','Chill','Oliva','Gusto 13','Fricska'];let aliases={'Elefánt':'Elefánt étterem','Chill':'Chill Bistro','Oliva':'Oliva Hotel és Étterem','Gusto 13':'Gusto13 Bistro & Delicate','Fricska':'Fricska Veszprém'};function get(name,platform){let exact=social.find(r=>r[0]==='Followers'&&r[1]===name&&String(r[2]||'').startsWith(platform)&&/^(követő|followers)$/i.test(String(r[3]||''))&&/^\d+$/.test(String(r[4]||'')));if(exact)return {value:Number(exact[4]),display:new Intl.NumberFormat('hu-HU').format(Number(exact[4])),date:exact[5],url:exact[6],note:exact[7]};let r=live.find(r=>r[0]===aliases[name]&&r[1]===platform);let s=String(r?.[3]||'');if(/^\d[\d,]*$/.test(s))return {value:Number(s.replace(/,/g,'')),display:new Intl.NumberFormat('hu-HU').format(Number(s.replace(/,/g,''))),date:'2026-11-09',url:r[2],note:'Nyilvános profil megfigyelése'};return {value:null,display:'Nem ellenőrzött',date:'2026-11-09',url:r?.[2],note:'A forrásban nem olvasható'};}let postStart=live.findIndex(r=>r[0]==='Posts');let postRows=postStart<0?[]:live.slice(postStart+2).filter(r=>r[0]&&r[1]&&r[3]);let metric=v=>v==null||v===''||v==='-'||v==='not read'?'Nem látható / nem olvasható':v;let profile=(name,platform)=>{let end=postStart<0?live.length:postStart;let r=live.slice(0,end).find(x=>x[0]===name&&x[1]===platform);return r&&/^https?:\/\//i.test(String(r[2]||''))?`<a href="${esc(r[2])}" target="_blank" rel="noopener">Profil megnyitása ↗</a>`:'Profil linkje nem ismert'};function chart(platform){let list=groups.map(name=>({name,...get(name,platform)}));let max=Math.max(1,...list.map(x=>x.value||0));return `<section class="panel"><h2>${esc(platform)} · követők</h2><p class="muted">Megfigyelések, nem élő adatok · ${platform==='Facebook'?'Az Oliva közös hotel- és étteremoldal.':'A hiányzó érték nem nulla.'}</p>${list.map(x=>`<div style="margin:1rem 0"><div><b>${esc(x.name)}</b> · ${esc(x.display)}</div>${x.value===null?'':`<div class="offer-track"><div style="width:${100*x.value/max}%"></div></div>`}<small>Megfigyelés: ${esc(x.date||'nem ismert')} · ${link(x.url)} · ${esc(x.note||'')}</small></div>`).join('')}</section>`};return title('06 / MARKETINGBENCHMARK','Hogyan vannak jelen mások?','A korábbi kutatásban megfigyelt nyilvános közösségi profilok összehasonlítása.')+note('A követőszám nem azonos az eléréssel, vendégszámmal vagy forgalommal. A megfigyelések 2026. november 9-iek. A Gusto Delicate külön profil, követőit nem adjuk hozzá a Gusto 13-hoz.')+`<div class="grid2">${chart('Facebook')}${chart('Instagram')}</div><p class="muted">Az Instagramon ahol a részletes forrás nem volt olvasható, a másik, kézzel rögzített megfigyelést használjuk; ahol nincs számszerű adat, nem becsülünk. A link hiánya nem jelenti a profil hiányát.</p><h2>Mit kommunikálnak a helyek?</h2><p>A 2026. november 9-i kutatásban rögzített példák. A posztok eltérő időpontokból származnak, ezért az aktivitásuk közvetlenül nem rangsorolható. A „–” azt jelenti, hogy szám nem volt látható, nem feltétlenül nulla.</p><div class="form"><label>Étterem<select id="post-filter"><option value="">Összes étterem</option>${[...new Set(postRows.map(r=>r[0]))].sort().map(n=>`<option value="${esc(n)}" ${n===postFilter?'selected':''}>${esc(n)}</option>`).join('')}</select></label><button class="small-btn" id="post-reset">Szűrő törlése</button></div><div class="grid2">${postRows.filter(r=>!postFilter||r[0]===postFilter).map(r=>`<article class="panel"><span class="pill">${esc(r[1]||'Ismeretlen platform')} · ${esc(r[2]||'Ismeretlen időpont')}</span><h3>${esc(r[0])}</h3><p>${esc(r[3]||'Téma nem ismert')}</p><p>Reakció: <b>${esc(metric(r[4]))}</b> · Hozzászólás: <b>${esc(metric(r[5]))}</b> · Megosztás: <b>${esc(metric(r[6]))}</b></p><p class="muted">Megfigyelés: 2026-11-09 · ${profile(r[0],r[1])}</p></article>`).join('')||'<p>Nincs megjeleníthető posztpélda.</p>'}</div><h2>Források és részletek</h2>${raw('Social and ads')}${raw('Social live read 2026-11-09')}`}
function quality(){return title('07 / KUTATÁSI MINŐSÉG','Mit tudunk biztosan?','A munkafüzet mentett pillanatképe böngészhető. Az egyes sorok dátuma, forrása és megjegyzése fontosabb, mint a betöltés dátuma.')+note(`Utolsó sikeres adatkivonat: ${esc(snapshot.imported_at||'nem ismert')}. A fájl a Google Sheet mentett pillanatképe. Automatikus szinkronizálás és önkiszolgáló import jelenleg nem működik; a frissítéshez új kivonat és telepítés szükséges.`)+`<div class="panel"><h2>Korábbi böngészők</h2><p>A korábbi kutatási nézetek is elérhetők.</p>${[['places','Éttermek'],['foods','Ételek'],['prices','Árak'],['future','Merre tovább?']].map(([id,label])=>`<button class="small-btn legacy" data-legacy="${id}">${label}</button> `).join('')}</div>`+Object.keys(data).map(n=>raw(n)).join('')}
function calculate(){let val=id=>Number(document.getElementById(id)?.value);if(document.getElementById('marginout')){let p=val('base'),f=val('food')/100,c=val('comm')/100,pk=val('pack'),sv=val('service'),m=val('markup')/100,d=p*(1+m),di=p-p*f-sv,de=d*(1-c)-p*f-pk,br=p>0&&c<1?((di+p*f+pk)/(p*(1-c))-1)*100:null;document.getElementById('marginout').innerHTML=`<div class="grid2"><div><p>Helyszíni fedezet / rendelés<br><b class="number">${fmt(di)}</b></p><p>Fedezeti arány: ${p>0?(di/p*100).toFixed(1)+'%':'—'}</p></div><div><p>Kiszállítási fedezet / rendelés<br><b class="number">${fmt(de)}</b></p><p>Fedezeti arány: ${d>0?(de/d*100).toFixed(1)+'%':'—'}</p></div></div><p>Különbség: <b>${fmt(de-di)}</b> · Azonos fedezethez szükséges felár: <b>${br===null?'nem számítható':br.toFixed(1)+'%'}</b></p>`;let o=val('orders'),cap=val('capacity'),s=Math.min(100,val('share'))/100,peak=val('peak'),lost=val('displace');document.getElementById('capacityout').innerHTML=`<p>Átlagos kihasználtság: <b>${cap>0?(o/cap*100).toFixed(0)+'%':'nem számítható'}</b> · csúcsidő: <b>${cap>0?(peak/cap*100).toFixed(0)+'%':'nem számítható'}</b></p><p>Becsült kiszállítási fedezet: <b>${fmt(o*s*de)} / óra</b> · kiszoruló helyszíni fedezet: <b>${fmt(lost*di)} / óra</b> · különbség: <b>${fmt(o*s*de-lost*di)} / óra</b></p><p>${cap<=0?'⚠ A kapacitás nem számítható; adj meg nullánál nagyobb értéket.':peak>cap?'⚠ A csúcsigény meghaladja a megadott kapacitást; kiszállítási limit vizsgálandó.':'A bemenetek alapján a csúcsidős igény nem haladja meg a megadott kapacitást.'}</p>`}if(document.getElementById('lresult')){let p=val('lprice'),c=val('lcost');document.getElementById('lresult').innerHTML=`Ételköltség utáni egyszerű különbözet: <b>${fmt(p*(1-c/100))} / menü</b>`}}
function render(){root.innerHTML=[()=>window.meetingViews.overview(data,snapshot),menu,()=>window.meetingViews.lunch(data),delivery,competition,marketing,quality,()=>window.renderMenuViz(data)][active]();nav.querySelectorAll('button').forEach(b=>b.classList.toggle('on',Number(b.dataset.i)===active || (active===1 && Number(b.dataset.i)===7)));root.querySelectorAll('[data-legacy]').forEach(b=>b.onclick=()=>document.querySelector(`header nav button[data-page="${b.dataset.legacy}"]`).click());root.querySelectorAll('[data-go]').forEach(a=>a.onclick=e=>{e.preventDefault();active=+a.dataset.go;render()});let q=document.getElementById('intel-query');if(q)q.oninput=e=>{let pos=e.target.selectionStart;query=e.target.value;render();let n=document.getElementById('intel-query');n.focus();n.setSelectionRange(pos,pos)};let clear=document.getElementById('clear-query');if(clear)clear.onclick=()=>{query='';render()};let lv=document.getElementById('lunch-view');if(lv)lv.onchange=e=>{window.lunchPay=e.target.value==='pay';render()};root.querySelectorAll('input[type=number]').forEach(x=>x.oninput=calculate);calculate();if(active===5){let pf=document.getElementById('post-filter');if(pf)pf.onchange=e=>{postFilter=e.target.value;render()};let pr=document.getElementById('post-reset');if(pr)pr.onclick=()=>{postFilter='';render()}}if(active===7)window.mountMenuViz(data,render);if(active===2)window.meetingViews.mount(render)}
nav.innerHTML=names.map(([x,i])=>`<button type="button" data-i="${i}">${esc(x)}</button>`).join('');nav.onclick=e=>{let b=e.target.closest('button');if(!b)return;active=+b.dataset.i;old.hidden=true;root.hidden=false;render();window.scrollTo(0,0)};document.querySelectorAll('header nav button').forEach(b=>b.addEventListener('click',()=>{root.hidden=true;old.hidden=false;nav.querySelectorAll('button').forEach(x=>x.classList.remove('on'))}));Promise.all([fetch('research.json').then(r=>{if(!r.ok)throw Error();return r.json()}),fetch('snapshot-meta.json').then(r=>r.ok?r.json():{}).catch(()=>({})),fetch('data2.json').then(r=>{if(!r.ok)throw Error();return r.json()})]).then(([d,m,lunch])=>{data=d;data['Napi menü árak']=lunch;snapshot=m;old.hidden=true;root.hidden=false;render()}).catch(()=>{old.hidden=false;root.hidden=true;nav.hidden=true})})();
